# G315: stderr ssh-клиента не должен печатать хост/порт в публичный лог Actions
# (маскировка GitHub знает только целое значение секрета, а ssh печатает части).
# Удалённый скрипт при этом выводит диагностику в stdout — она не глушится.
# Код выхода ssh сохраняется: 255 → наши шаги отрабатывают как раньше.
ssh() { command ssh "$@" 2>/dev/null; }
scp() { command scp "$@" 2>/dev/null; }
